function sortChain(head: ListNode | null): ListNode | null {
  const dummy = new ListNode(0);
  while (head) {
    const node = head;
    head = head.next;
    let p = dummy;
    while (p.next && p.next.val <= node.val) p = p.next;
    node.next = p.next;
    p.next = node;
  }
  return dummy.next;
}

