class Solution:
    def sortChain(self, head: Optional[ListNode]) -> Optional[ListNode]:
        dummy = ListNode(0)
        while head:
            node, head = head, head.next
            p = dummy
            while p.next and p.next.val <= node.val:
                p = p.next
            node.next, p.next = p.next, node
        return dummy.next

